    ('view', 'public.org_member', 'security_invoker=true  SELECT clinic_id AS org_id,
    id AS user_id,
    COALESCE(org_role, ''technician''::text) AS role,
    language
   FROM profiles
  WHERE ((clinic_id IS NOT NULL) AND (role = ANY (ARRAY[''owner''::text, ''worker''::text])));'),
    ('view', 'public.organization', 'security_invoker=true  SELECT id,
    name,
    country,
    default_language,
    home_instance,
    code_prefix,
    created_at
   FROM clinics;'),
    ('view', 'public.partner_job_view', 'security_invoker=true  SELECT share_id,
    job_id,
    job_code,
    owner_org,
    owner_org_name,
    case_type,
    visibility,
    role,
    assigned_stages,
    status,
    can_move,
    next_stage,
    received_on,
    due_at,
    work_type,
    work_items,
    teeth,
    material,
    shade,
    stump_shade,
    description,
    rush,
    model,
    revisions,
    partner_price,
    patient_age,
    patient_sex,
    patient_name,
    patient_phone,
    patient_email,
    open_questions,
    shared_at
   FROM partner_jobs() partner_jobs(share_id, job_id, job_code, owner_org, owner_org_name, case_type, visibility, role, assigned_stages, status, can_move, next_stage, received_on, due_at, work_type, work_items, teeth, material, shade, stump_shade, description, rush, model, revisions, partner_price, patient_age, patient_sex, patient_name, patient_phone, patient_email, open_questions, shared_at);'),
    ('view', 'public.stock_levels', 'security_invoker=true  SELECT id,
    org_id,
    owner_org,
    owner_supplier,
    category,
    manufacturer,
    system,
    size,
    product,
    lot,
    expiry_date,
    consignment_due,
    archived_at,
    created_by,
    created_at,
    product_key,
    (COALESCE(( SELECT sum(m.delta) AS sum
           FROM stock_movement m
          WHERE (m.item_id = i.id)), (0)::bigint))::integer AS qty
   FROM stock_item i;'),
    ('view', 'public.stock_product_levels', 'security_invoker=true  SELECT l.org_id,
    l.product_key,
    min(l.category) AS category,
    max(l.manufacturer) AS manufacturer,
    max(l.system) AS system,
    max(l.size) AS size,
    max(l.product) AS product,
    (COALESCE(sum(l.qty) FILTER (WHERE (l.archived_at IS NULL)), (0)::bigint))::integer AS qty,
    (count(*) FILTER (WHERE ((l.archived_at IS NULL) AND (l.qty > 0))))::integer AS lots,
    t.min_qty
   FROM (stock_levels l
     LEFT JOIN stock_threshold t ON (((t.org_id = l.org_id) AND (t.product_key = l.product_key))))
  GROUP BY l.org_id, l.product_key, t.min_qty;')
),
actual as (select * from (
select 'trigger'::text as kind, n.nspname || '.' || c.relname || '.' || t.tgname as key, pg_get_triggerdef(t.oid) as def
  from pg_trigger t
  join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace
  join pg_proc p on p.oid = t.tgfoid join pg_namespace pn on pn.oid = p.pronamespace
 where not t.tgisinternal and pn.nspname = 'public'
union all
select 'index', 'public.' || ic.relname, pg_get_indexdef(i.indexrelid)
  from pg_index i
  join pg_class ic on ic.oid = i.indexrelid
  join pg_class tc on tc.oid = i.indrelid join pg_namespace n on n.oid = tc.relnamespace
 where n.nspname = 'public'
   and not exists (select 1 from pg_constraint k where k.conindid = i.indexrelid and k.contype in ('p', 'u', 'x'))
union all
select 'constraint', 'public.' || tc.relname || '.' || k.conname, pg_get_constraintdef(k.oid)
  from pg_constraint k
  join pg_class tc on tc.oid = k.conrelid join pg_namespace n on n.oid = tc.relnamespace
 where n.nspname = 'public' and k.contype in ('p', 'u', 'c', 'f', 'x')
union all
select 'not null', 'public.' || tc.relname || '.' || a.attname, 'not null'
  from pg_attribute a
  join pg_class tc on tc.oid = a.attrelid join pg_namespace n on n.oid = tc.relnamespace
 where n.nspname = 'public' and tc.relkind in ('r', 'p') and a.attnum > 0 and not a.attisdropped and a.attnotnull
union all
select 'default', 'public.' || tc.relname || '.' || a.attname, pg_get_expr(d.adbin, d.adrelid)
  from pg_attrdef d
  join pg_attribute a on a.attrelid = d.adrelid and a.attnum = d.adnum
  join pg_class tc on tc.oid = d.adrelid join pg_namespace n on n.oid = tc.relnamespace
 where n.nspname = 'public'
union all
select 'identity', 'public.' || tc.relname || '.' || a.attname, case a.attidentity when 'a' then 'always' else 'by default' end
  from pg_attribute a
  join pg_class tc on tc.oid = a.attrelid join pg_namespace n on n.oid = tc.relnamespace
 where n.nspname = 'public' and a.attidentity <> '' and not a.attisdropped
union all
select 'sequence owner', 'public.' || s.relname, tc.relname || '.' || a.attname
  from pg_class s
  join pg_namespace n on n.oid = s.relnamespace
  join pg_depend d on d.objid = s.oid and d.classid = 'pg_class'::regclass and d.refclassid = 'pg_class'::regclass and d.deptype in ('a', 'i')
  join pg_class tc on tc.oid = d.refobjid
  join pg_attribute a on a.attrelid = tc.oid and a.attnum = d.refobjsubid
 where s.relkind = 'S' and n.nspname = 'public'
union all
select 'view', 'public.' || c.relname, coalesce(array_to_string(c.reloptions, ','), '') || ' ' || pg_get_viewdef(c.oid)
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
 where c.relkind in ('v', 'm') and n.nspname = 'public'
union all
select 'row security', 'public.' || c.relname,
       case when c.relforcerowsecurity then 'on, forced' when c.relrowsecurity then 'on' else 'off' end
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
 where n.nspname = 'public' and c.relkind in ('r', 'p')
union all
select 'policy', p.schemaname || '.' || p.tablename || '.' || p.policyname,
       p.permissive || ' ' || p.cmd || ' to ' || array_to_string(p.roles, ',')
         || ' using (' || coalesce(p.qual, '') || ') check (' || coalesce(p.with_check, '') || ')'
  from pg_policies p
 where p.schemaname in ('public', 'storage')
) catalog),
norm as (
  select coalesce(e.kind, a.kind) as kind, coalesce(e.key, a.key) as key,
         e.def as expected, a.def as actual
    from expected e full join actual a on a.kind = e.kind and a.key = e.key
)
select kind, key,
       case when actual is null then 'missing' when expected is null then 'extra' else 'differs' end as status,
       expected, actual
  from norm
 where actual is null or expected is null
    or regexp_replace(lower(actual), '\s+', ' ', 'g') <> regexp_replace(lower(expected), '\s+', ' ', 'g')
 order by 3, 1, 2;
